import{_ as l,a0 as p,w as o,s as d,ao as r,I as t,x as s,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"如何在 RHEL 9 上配置 DHCP 服務器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 RHEL 9 上配置 DHCP 服務器 | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 RHEL 9 上配置 DHCP 服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 RHEL 9 上配置 DHCP 服務器 | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20230425.0 ⭐️⭐️ How to Configure DHCP Server on RHEL 9  Rocky Linux 9","title":"如何在 RHEL 9 上配置 DHCP 服務器","tag":"202305","desc":""},"relativePath":"202305/20230425.0 ⭐️⭐️ How to Configure DHCP Server on RHEL 9  Rocky Linux 9.md","filePath":"[post].md"}'),c={name:"202305/20230425.0 ⭐️⭐️ How to Configure DHCP Server on RHEL 9  Rocky Linux 9.md"};function h(u,e,g,k,m,b){const i=p("Link");return o(),d("div",null,[e[15]||(e[15]=r(`<h1 id="如何在-rhel-9-上配置-dhcp-服務器" tabindex="-1">如何在 RHEL 9 上配置 DHCP 服務器 <a class="header-anchor" href="#如何在-rhel-9-上配置-dhcp-服務器" aria-label="Permalink to “如何在 RHEL 9 上配置 DHCP 服務器”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202305/24/113729hi6cn36hicjgknjy.jpg" alt=""></p><p>DHCP 是 “<ruby>動態主機配置協議<rt>Dynamic Host Configuration Protocol</rt></ruby>” 的首字母縮寫詞，它是一種網絡協議，可自動為計算機網絡中的客户端系統分配 IP 地址。它從 DHCP 池或在其配置中指定的 IP 地址範圍分配客户端。雖然你可以手動為客户端系統分配靜態 IP，但 DHCP 服務器簡化了這一過程，併為網絡上的客户端系統動態分配 IP 地址。</p><p>在本文中，我們將演示如何在 RHEL 9 / Rocky Linux 9 上安裝和配置 DHCP 服務器。</p><h3 id="先決條件" tabindex="-1">先決條件 <a class="header-anchor" href="#先決條件" aria-label="Permalink to “先決條件”">​</a></h3><ul><li>預裝 RHEL 9 或 Rocky Linux 9</li><li>具有 sudo 管理權限的普通用户</li><li>本地配置的 YUM/DNF 倉庫或 RHEL 9 的 Red Hat 訂閲</li><li>互聯網連接</li></ul><p>事不宜遲，讓我們進入 DHCP 服務器安裝步驟。</p><h3 id="_1、在-rhel-9-rocky-linux-9-上配置靜態-ip-地址" tabindex="-1">1、在 RHEL 9 / Rocky Linux 9 上配置靜態 IP 地址 <a class="header-anchor" href="#_1、在-rhel-9-rocky-linux-9-上配置靜態-ip-地址" aria-label="Permalink to “1、在 RHEL 9 / Rocky Linux 9 上配置靜態 IP 地址”">​</a></h3><p>開始時，必須在 RHEL 或 Rocky Linux 系統上設置靜態 IP 地址。有多種方法可以執行此操作，但最簡單和最直觀的方法是使用 <code>nmtui</code> 或 <code>nmcli</code> 實用程序。</p><p>要確認你的 Linux 系統的 IP 地址，請運行以下 <code>ip</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip a</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Confirm-IP-Address-RHEL-RockyLinux.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><h3 id="_2、安裝和配置-dhcp-服務器" tabindex="-1">2、安裝和配置 DHCP 服務器 <a class="header-anchor" href="#_2、安裝和配置-dhcp-服務器" aria-label="Permalink to “2、安裝和配置 DHCP 服務器”">​</a></h3><p>配置靜態 IP 後，下一步就是安裝 DHCP 服務器。RHEL 9 或 Rocky Linux 9 倉庫 (BaseOS) 默認提供 <code>dhcp-server</code> 包，你可以如圖所示安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install dhcp-server -y</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Install-DHCP-Server-DNF-Command.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>安裝 dhcp 服務器後，我們需要進一步並配置設置。因此，打開 DHCP 配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/dhcp/dhcpd.conf</span></span></code></pre></div><p>將以下代碼行粘貼到配置文件中。請務必將子網配置為你的首選值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>default-lease-time 3600;</span></span>
<span class="line"><span>max-lease-time 86400;</span></span>
<span class="line"><span>authoritative;</span></span>
<span class="line"><span>subnet 192.168.10.0 netmask 255.255.255.0 {</span></span>
<span class="line"><span>    range 192.168.10.100 192.168.10.200;</span></span>
<span class="line"><span>    option routers 192.168.10.1;</span></span>
<span class="line"><span>    option subnet-mask 255.255.255.0;</span></span>
<span class="line"><span>    option domain-name-servers 192.168.10.1;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>保存並關閉文件。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/DHCP-Conf-File-RHEL-RockyLinux.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>讓我們看一下其中的一些值：</p><ul><li><code>default-lease-time</code> 值指定 DHCP 服務器將地址租給客户端的時間。在這種情況下，默認租用時間值為 3600 秒或 1 小時。</li><li><code>max-lease-time</code> 是將 IP 租給客户端的最長持續時間。在我們的例子中，這被設置為 86400 秒或 24 小時。</li><li>下一部分是子網配置。在此設置中，<code>192.168.10.0</code> 是子網，<code>255.255.255.0</code> 是子網掩碼。IP 地址範圍從 <code>192.168.10.100</code> 一直到 <code>192.168.10.200</code>。</li><li><code>router</code> 選項定義默認網關。在本例中為 <code>192.168.10.1</code>。</li><li><code>subnet-mask</code> 選項確定分配給每個客户端或主機的子網掩碼。在本例中為 <code>255.255.255.0</code>。</li><li>最後，<code>domain-name-servers</code> 選項指定 DNS 服務器。在本例中為 <code>192.168.10.1</code>。</li></ul><p>完成後，保存更改並退出。然後啓用並啓動 DHCP 服務。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable --now dhcpd</span></span>
<span class="line"><span>$ sudo systemctl status dhcpd</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/DHCP-Server-Service-Status-RHEL-RockyLinux.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>請注意：</p><p>此時，DHCP 服務應該分發 IP 地址。如果你的 LAN 中有另一個 DHCP 服務器或路由器，關閉它以防止 IP 地址分配衝突是明智的。這將導致一些客户端從 RHEL 或 Rocky Linux 服務器上的 DHCP 服務器獲得 IP 分配，而其餘的則從路由器獲得 IP 分配，這當然不是你想要發生的事情。因此，請記住關閉 LAN 設置中的任何其他 DHCP 服務器。</p><h3 id="_3、測試-dhcp-服務器安裝" tabindex="-1">3、測試 DHCP 服務器安裝 <a class="header-anchor" href="#_3、測試-dhcp-服務器安裝" aria-label="Permalink to “3、測試 DHCP 服務器安裝”">​</a></h3><p>在我們模擬的 LAN 設置中，你可以看到 Ubuntu 系統已經從 RHEL 或 Rocky Linux DHCP 服務器中選擇了一個 IP。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Automatic-Assign-DHCP-Server-RHEL-RockyLinux-1024x584.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>回到我們的 DHCP 服務器並在 <code>/var/log/message</code> 文件中搜索 Ubuntu 機器的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo tail -50 /var/log/messages | grep -i 192.168.10.100</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/DHCP-Server-Logs-RHEL-RockyLinux-1024x116.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>完美，上面的輸出確認 Ubuntu 機器從我們的 DHCP 服務器獲得了 IP 服務器。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>這篇文章到此結束。在本指南中，你學習瞭如何在 RHEL 9 / Rocky Linux 9 上安裝和配置 DHCP 服務器。請在下面的評論部分發表你的疑問和反饋。</p><p>（題圖：MJ/d396485d-963c-4d17-8c4b-f3c8e11dcc5d）</p><hr>`,40)),t("p",null,[e[1]||(e[1]=s("via: ",-1)),a(i,{href:"https://www.linuxtechi.com/configure-dhcp-server-on-rhel-rockylinux/"},{default:n(()=>[...e[0]||(e[0]=[s("https://www.linuxtechi.com/configure-dhcp-server-on-rhel-rockylinux/",-1)])]),_:1})]),t("p",null,[e[6]||(e[6]=s("作者：",-1)),a(i,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...e[2]||(e[2]=[s("Pradeep Kumar",-1)])]),_:1}),e[7]||(e[7]=s(" 選題：",-1)),a(i,{href:"https://github.com/lkxed/"},{default:n(()=>[...e[3]||(e[3]=[s("lkxed",-1)])]),_:1}),e[8]||(e[8]=s(" 譯者：",-1)),a(i,{href:"https://github.com/geekpi"},{default:n(()=>[...e[4]||(e[4]=[s("geekpi",-1)])]),_:1}),e[9]||(e[9]=s(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=s("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...e[11]||(e[11]=[s("Linux中國",-1)])]),_:1}),e[14]||(e[14]=s(" 榮譽推出",-1))])])}const f=l(c,[["render",h]]);export{P as __pageData,f as default};
